        elif a.startswith('--max-lines='): maxlines=int(a.split('=',1)[1])
        elif a=='--tail-lines' and i+1<len(args): tail=int(args[i+1]); i+=2; continue
        elif a.startswith('--tail-lines='): tail=int(a.split('=',1)[1])
