"""Standalone log output compaction used by the RTK-compatible CLI."""
from collections import Counter
import re
import sys

_ERROR = re.compile(r"\b(error|fatal|critical|panic)\b", re.I)
_WARN = re.compile(r"\b(warn(?:ing)?)\b", re.I)
_INFO = re.compile(r"\b(info)\b", re.I)


def compact_log(text: str, ultra: bool = False) -> str:
    errors, warnings, infos = [], [], []
    for line in text.splitlines():
        s = line.strip()
        if not s:
            continue
        if _ERROR.search(s):
            errors.append(s)
        elif _WARN.search(s):
            warnings.append(s)
        elif _INFO.search(s):
            infos.append(s)
    def unique(items):
        counts = Counter(items)
        return [(s, counts[s]) for s in dict.fromkeys(items)]
    e, w = unique(errors), unique(warnings)
    out = ["Log Summary", f"   [error] {len(errors)} errors ({len(e)} unique)",
           f"   [warn] {len(warnings)} warnings ({len(w)} unique)",
           f"   [info] {len(infos)} info messages", ""]
    for title, items in (("ERRORS", e), ("WARNINGS", w)):
        if not items:
            continue
        out.append(f"[{title}]")
        for line, count in items:
            prefix = f"[×{count}] " if count > 1 else ""
            out.append("   " + prefix + line)
        out.append("")
    return "\n".join(out).rstrip() + "\n"


def run_log(path=None, stdin=None, ultra=False):
    try:
        if path:
            with open(path, "r", encoding="utf-8", errors="replace") as f:
                data = f.read()
        else:
            data = sys.stdin.read() if stdin is None else stdin
    except OSError as exc:
        print(f"rtk: {exc}", file=sys.stderr)
        return 1
    sys.stdout.write(compact_log(data, ultra))
    return 0
"""Command rewriting used by RTK's hook integrations."""
import os
import re
import shlex

# Commands with native filters. More entries are intentionally accepted: the
# reference ships filters for a broad set of developer tools.
SUPPORTED = set('''ls tree read smart git gh glab aws psql pnpm err test json deps env find diff log dotnet docker kubectl summary grep init wget wc gain cc-economics config jest vitest prisma tsc next lint prettier format playwright cargo npm npx curl discover session telemetry learn run proxy pipe trust untrust verify ruff pytest mypy rake rubocop rspec pip go gt golangci-lint gradlew hook-audit rewrite hook terraform make brew composer poetry helm rsync'''.split())

def _rewrite_segment(segment):
    """Rewrite one shell command while retaining its original spelling."""
    # Preserve leading whitespace and shell assignments/prefixes.
    m = re.match(r'^(\s*)((?:[A-Za-z_][A-Za-z0-9_]*=[^\s]+\s+)*)(.*)$', segment, re.S)
    if not m:
        return segment, False
    lead, envs, body = m.groups()
    if not body.strip():
        return segment, False
    try:
        words = shlex.split(body, posix=True)
    except ValueError:
        return segment, False
    if not words:
        return segment, False
    # Do not rewrite shell builtins, paths, or arbitrary executables.
    cmd = words[0]
    if cmd in ('sudo', 'command', 'time', 'env') and len(words) > 1:
        prefix = cmd + ' '
        sub = ' '.join(words[1:])
        rewritten, ok = _rewrite_segment(sub)
        if ok:
            return lead + envs + prefix + rewritten.strip(), True
        return segment, False
    if '/' in cmd or cmd.startswith('-'):
        return segment, False
    if cmd == 'rtk':
        return segment, True
    aliases = {'cat': 'read', 'rg': 'grep', 'fd': 'find'}
    if cmd in SUPPORTED or cmd in aliases:
        if cmd in aliases:
            target = aliases[cmd]
        else:
            target = cmd
        # `ls` and others are dispatched by rtk; retain arguments verbatim.
        rewritten = target + body[len(cmd):]
        return lead + envs + 'rtk ' + rewritten, True
    return segment, False

def rewrite(command):
    """Return (rewritten command, changed/supported). Compound shell commands
    are rewritten clause by clause, leaving operators and unsupported clauses."""
    if not command.strip():
        return '', False
    if os.environ.get('RTK_DISABLED') == '1':
        return '', False
    # Split on shell control operators outside quotes. The RTK hook deliberately
    # leaves heredocs and complex constructs alone.
    chunks = re.split(r'((?:&&|\|\||;|\|)\s*)', command)
    any_supported = False
    for i in range(0, len(chunks), 2):
        part, ok = _rewrite_segment(chunks[i])
        chunks[i] = part
        any_supported |= ok
    return ''.join(chunks), any_supported

