"""JSON adapters for the supported agent hook protocols."""
import json
from rewrite_util import rewrite

def process(agent, raw):
    try:
        obj = json.loads(raw)
    except Exception:
        return ''
    if not isinstance(obj, dict):
        obj = {}
    inp = obj.get('tool_input')
    if not isinstance(inp, dict):
        inp = {}
    command = inp.get('command')
    # Gemini calls its shell tool run_shell_command; other tool names are
    # intentionally ignored by its adapter.
